21	     * Stops the meeting immediately, snapshots data, and triggers background processing.
22	     * Returns immediately so UI can switch.
23	     */
24	    public async stopMeeting(): Promise<string | null> {
25	        console.log('[MeetingPersistence] Stopping meeting and queueing save...');
26	
27	        // 0. Force-save any pending interim transcript
28	        this.session.flushInterimTranscript();
29	
30	        // 1. Snapshot valid data BEFORE resetting
31	        const durationMs = Date.now() - this.session.getSessionStartTime();
32	        if (durationMs < 1000) {
33	            console.log("Meeting too short, ignoring.");
34	            this.session.reset();
35	            return null;
36	        }
37	
38	        const snapshot = {
39	            transcript: [...this.session.getFullTranscript()],
40	            usage: [...this.session.getFullUsage()],
41	            startTime: this.session.getSessionStartTime(),
42	            durationMs: durationMs,
43	            context: this.session.getFullSessionContext()
44	        };
45	
46	        // BUG-04 fix: snapshot metadata BEFORE reset() clears it so the
47	        // background processAndSaveMeeting worker receives the calendar info.
48	        const metadataSnapshot = this.session.getMeetingMetadata();
49	
50	        // 2. Reset state immediately so new meeting can start or UI is clean
51	        this.session.reset();
52	
53	        const meetingId = crypto.randomUUID();
54	        this.processAndSaveMeeting(snapshot, meetingId, metadataSnapshot).catch(err => {
55	            console.error('[MeetingPersistence] Background processing failed:', err);
56	        });
57	
58	        // 4. Initial Save (Placeholder)
59	        const minutes = Math.floor(durationMs / 60000);
60	        const seconds = ((durationMs % 60000) / 1000).toFixed(0);
61	        const durationStr = `${minutes}:${Number(seconds) < 10 ? '0' : ''}${seconds}`;
62	
63	        const placeholder: Meeting = {
64	            id: meetingId,
65	            title: "Processing...",
66	            date: new Date().toISOString(),
67	            duration: durationStr,
68	            summary: "Generating summary...",
69	            detailedSummary: { actionItems: [], keyPoints: [] },
70	            transcript: snapshot.transcript,
71	            usage: snapshot.usage,
72	            isProcessed: false
73	        };
74	
75	        try {
76	            DatabaseManager.getInstance().saveMeeting(placeholder, snapshot.startTime, durationMs);
77	            // Notify Frontend
78	            const wins = require('electron').BrowserWindow.getAllWindows();
79	            wins.forEach((w: any) => w.webContents.send('meetings-updated'));
80	        } catch (e) {
81	            console.error("Failed to save placeholder", e);
82	        }
83	
84	        return meetingId;
85	    }
